<?php require 'common.php'; $mode=lab_mode(); $q=$_GET['q']??''; audit('XSS DOM',$mode,'GET',$_SERVER['REQUEST_URI']??'',200,$mode==='fixed'?'encoded':'dom-sink','DOM sink is intentionally unsafe in vulnerable mode.'); ?><!doctype html><html lang="vi"><head><meta charset="utf-8"><title>DOM XSS Lab</title></head><body style="font-family:Arial;max-width:950px;margin:30px auto"><h1>DOM-based XSS</h1><p>Mode: <?=h($mode)?></p><form><input name="q" value="<?=h($q)?>" size="60"><select name="mode"><option value="vulnerable">vulnerable</option><option value="fixed">fixed</option></select><button>Load</button></form><div id="out" style="border:1px solid #ccc;padding:15px;margin-top:15px"></div><script>const q=<?=json_encode($q,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT)?>;const out=document.getElementById('out');<?php if($mode==='vulnerable'): ?>out.innerHTML=q;<?php else: ?>out.textContent=q;<?php endif; ?></script><p>Fixed: không đưa dữ liệu không tin cậy vào HTML sink; dùng textContent hoặc context-aware encoding.</p><a href="index.php">← Lab menu</a></body></html>